cat >> src/orchestration/orchestratorHelpers.test.ts <<'EOF'

describe('addUsage', () => {
  it('leaves a turn with no reported usage undefined', () => {
    expect(addUsage(undefined, undefined)).toBeUndefined();
  });

  it('sums each token field across the rounds that reported usage', () => {
    const first = {inputTokens: 11, outputTokens: 2, totalTokens: 13};
    const second = {inputTokens: 23, outputTokens: 3, totalTokens: 26};

    expect(addUsage(first, second)).toEqual({inputTokens: 34, outputTokens: 5, totalTokens: 39});
  });

  it('keeps the rounds that reported when a later round reported nothing', () => {
    const reported = {inputTokens: 4, outputTokens: 1, totalTokens: 5};

    expect(addUsage(reported, undefined)).toEqual(reported);
    expect(addUsage(undefined, reported)).toEqual(reported);
  });
});
EOF
